{
  "name": "oc-cbm",
  "version": "0.5.4",
  "description": "OpenCode CBM plugin with freshness-verified, relevance-filtered investigations and bounded project lifecycle management",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "SKILL.md",
    "README.md"
  ],
  "scripts": {
    "build": "tsc",
    "test": "npm run build && node --test test/*.test.mjs",
    "watch": "tsc --watch",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.18",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/node": "^22.20.1",
    "typescript": "^5.9.3"
  },
  "keywords": [
    "opencode",
    "plugin",
    "cbm",
    "codebase-memory",
    "mcp",
    "code-intelligence"
  ],
  "license": "MIT"
}

{
  "name": "oc-fs-tooling",
  "version": "2.2.0",
  "description": "Plain-language, evidence-rich OpenCode filesystem tools with adaptive reads, structured search/exploration evidence, and safe ordered atomic-write edit recovery.",
  "main": "index.js",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test/*.test.mjs"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.18"
  }
}

{
  "name": "@sparkly/selfpatch",
  "version": "1.4.0",
  "private": true,
  "type": "module",
  "description": "Update-safe OpenCode companion with portable plugin features and strictly verified optional host enhancements.",
  "main": "index.js",
  "exports": {
    ".": "./index.js",
    "./*": "./*"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs"
  }
}

{
  "name": "oc-enhanced-terminal",
  "version": "2.7.0",
  "description": "Self-healing, batch-oriented shell and background process tools with bounded same-call recovery and high-information lifecycle output for OpenCode.",
  "main": "index.js",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test/*.test.mjs"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.18"
  }
}

{
  "name": "@sparkly/toolings-tui",
  "version": "2.0.0",
  "private": true,
  "type": "module",
  "description": "OpenCode TUI companion with status-aware activity surfaces, hierarchical per-item inspector cards, and stable lifecycle-accurate transcript rendering.",
  "main": "index.tsx",
  "exports": {
    ".": "./index.tsx",
    "./*": "./*"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs"
  }
}
